  --device-screen-radius: 55px;
  --device-bezel: 12px;
  --device-scale: 1;

  /* Absolute + translate keeps the frame centered even when it overflows the viewport. */
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(var(--device-scale));
