    border: hex("#E4E4E7"),
    divider: hex("#F1F1F3"),
    title: hex("#18181B"),
    body: hex("#3F3F46"),
    muted: hex("#71717A"),
    faint: hex("#A1A1AA"),
    accent: hex("#FF6600"),
};

const CARD_WIDTH = 1240;
const COLUMN_GAP = 80;

// 루트 프레임 + 라벨만으로 그려지는 컴포넌트들. 축이 늘어나면 조합이 폭발하므로 직접 고른다.
const COMPONENT_SPECS = [
